// Some portions generated by Codex
// @ts-check
const { test, expect } = require('@playwright/test');
const { uniqueRepositoryId } = require('./workbench-test-helpers.js');

const DEV_URL = process.env.RDF4J_GRAPH_DEV_URL || 'http://127.0.0.1:5173/dev/index.html';
const REPOSITORY_ID = uniqueRepositoryId('graph-fixed-bnodes');
const SERVER_IDENTITY = 'sha256:graph-fixed-bnodes-browser-fixture';
const DEFAULT_QUERY = 'SELECT ?source ?predicate ?target WHERE { ?source ?predicate ?target } LIMIT 100';
const RDF_TYPE = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type';
const RDFS_LABEL = 'http://www.w3.org/2000/01/rdf-schema#label';

const uri = (value) => ({ type: 'uri', value });
const literal = (value) => ({ type: 'literal', value });
const blank = (value, certified = true) => ({
    type: 'bnode', value,
    ...(certified ? { 'rdf4j:reference': true } : {})
});
const binding = (source, predicate, target) => ({ source, predicate: uri(predicate), target });

const graphBindings = [
    binding(blank('alice'), RDF_TYPE, uri('urn:Person')),
    binding(blank('alice'), RDFS_LABEL, literal('Alice')),
    binding(blank('alice'), 'urn:knows', blank('bob')),
    binding(blank('bob'), RDFS_LABEL, literal('Bob')),
    binding(uri('urn:document'), RDFS_LABEL, literal('Document')),
    binding(uri('urn:document'), 'urn:mentions', blank('transient', false))
];

function sparqlResults(vars, bindings) {
    return JSON.stringify({ head: { vars }, results: { bindings } });
}

function graphLabels() {
    return sparqlResults(['resource', 'labelProperty', 'label'], [
        { resource: blank('alice'), labelProperty: uri(RDFS_LABEL), label: literal('Alice') },
        { resource: blank('bob'), labelProperty: uri(RDFS_LABEL), label: literal('Bob') },
        { resource: uri('urn:document'), labelProperty: uri(RDFS_LABEL), label: literal('Document') }
    ]);
}

/** A GraphServlet stand-in that preserves the selected server identity on identity and query responses. */
async function openGraph(page) {
    const postedQueries = [];
    const devOrigin = new URL(DEV_URL).origin;
    const graphPath = `/rdf4j-workbench/repositories/${encodeURIComponent(REPOSITORY_ID)}/graph`;

    await page.route('**/rdf4j-workbench/styles/workbench-refresh.css', (route) => route.fulfill({
        status: 200,
        contentType: 'text/css',
        body: ''
    }));
    await page.route((url) => url.origin === devOrigin && url.pathname === graphPath, async (route) => {
        const request = route.request();
        const headers = {
            'X-Workbench-Server-Identity': SERVER_IDENTITY,
            'Cache-Control': 'no-store'
        };
        if (request.method() === 'GET') {
            await route.fulfill({
                status: 200,
                headers: { ...headers, 'Content-Type': 'application/vnd.rdf4j.workbench+ndjson' },
                body: sparqlResults([], [])
            });
            return;
        }

        const query = request.postData() || '';
        postedQueries.push(query);
        let body = sparqlResults([], []);
        if (query === DEFAULT_QUERY) {
            body = sparqlResults(['source', 'predicate', 'target'], graphBindings);
        } else if (query.includes('SELECT DISTINCT ?resource ?labelProperty ?label')) {
            body = graphLabels();
        } else if (query.includes('SELECT ?selected ?predicate ?direction')) {
            body = sparqlResults(['selected', 'predicate', 'direction'], [
                { selected: blank('alice'), predicate: uri('urn:knows'), direction: literal('outgoing') },
                { selected: uri('urn:document'), predicate: uri('urn:mentions'), direction: literal('outgoing') }
            ]);
        }
        await route.fulfill({
            status: 200,
            headers: { ...headers, 'Content-Type': 'application/sparql-results+json' },
            body
        });
    });

    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(`${DEV_URL}?repository=${encodeURIComponent(REPOSITORY_ID)}`);
    await expect(page.getByRole('button', { name: 'Load 100 statements' })).toBeVisible();
    return postedQueries;
}

async function loadGraph(page) {
    await page.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(page.locator('.graph-node.blank').filter({ hasText: 'Alice' })).toBeVisible();
    await expect(page.locator('.graph-node.blank').filter({ hasText: 'Bob' })).toBeVisible();
    await expect(page.locator('.graph-node.iri').filter({ hasText: 'Document' })).toBeVisible();
}

test('stored blank nodes expose Explore and Expand in the inspector', async ({ page }) => {
    await openGraph(page);
    await loadGraph(page);

    await page.locator('.graph-node.blank').filter({ hasText: 'Alice' }).click();
    const details = page.locator('.node-details');
    await expect(details).toBeVisible();
    await expect(details.getByRole('button', { name: 'Expand', exact: true })).toBeVisible();
    const explore = details.getByRole('link', { name: 'Explore', exact: true });
    await expect(explore).toBeVisible();
    await expect(explore).toHaveAttribute('href', /\/explore\?resource=%3C_%3Aalice%3E$/);
    if (process.env.RDF4J_GRAPH_SCREENSHOT) {
        await page.screenshot({ path: process.env.RDF4J_GRAPH_SCREENSHOT, fullPage: true });
    }
});

test('Find uses the fixed blank reference as a SPARQL resource operand', async ({ page }) => {
    const postedQueries = await openGraph(page);
    await loadGraph(page);
    const find = page.getByRole('combobox', { name: 'Find a node, or search the repository' });
    await find.fill('<_:alice>');
    const repositorySearch = page.getByRole('option', { name: /Search the repository for “<_:alice>”/ });
    await expect(repositorySearch).toBeVisible();
    await repositorySearch.click();

    await expect.poll(() => postedQueries.some((query) => /VALUES \?source\s*\{\s*<_:alice>\s*\}/.test(query))).toBe(true);
    const searchQuery = postedQueries.find((query) => /VALUES \?source\s*\{\s*<_:alice>\s*\}/.test(query));
    expect(searchQuery).not.toContain('CONTAINS(?text');
});

test('a mixed-selection context menu keeps certified blank nodes in its relation query', async ({ page }) => {
    const postedQueries = await openGraph(page);
    await loadGraph(page);

    const alice = page.locator('.graph-node.blank').filter({ hasText: 'Alice' });
    const document = page.locator('.graph-node.iri').filter({ hasText: 'Document' });
    await alice.focus();
    await alice.press('Enter');
    await document.focus();
    await document.press('Shift+Enter');
    await expect(page.locator('.graph-node.is-selected')).toHaveCount(2);

    await alice.focus();
    await alice.press('Shift+F10');
    const menu = page.getByRole('dialog', { name: /Actions for Alice/ });
    await expect(menu.locator('.menu-header h3')).toHaveText('2 selected nodes');
    await menu.locator('.context-disclosure summary').click();
    await expect.poll(() => postedQueries.some((query) =>
        query.includes('SELECT ?selected ?predicate ?direction') &&
        query.includes('<_:alice>') && query.includes('<urn:document>'))).toBe(true);
});

test('named graph scope accepts a fixed blank reference', async ({ page }) => {
    const postedQueries = await openGraph(page);
    await loadGraph(page);

    await page.getByRole('button', { name: 'Query editor' }).click();
    const preferences = page.locator('.label-preferences');
    await preferences.locator('summary').click();
    await preferences.getByLabel('Graph scope').selectOption('named');
    await preferences.getByLabel('Named graph IRI').fill('<_:graph>');
    await preferences.getByRole('button', { name: 'Use graph' }).click();

    await expect(preferences.getByText('Enter a valid named graph IRI.')).toHaveCount(0);
    await expect.poll(() => postedQueries.some((query) => query.includes('GRAPH <_:graph>'))).toBe(true);
});
